  (source += ((mode == flight::types::fog_modifier_mode->linear) ? flight::String("uniform float u_fogNear") + flight::to_string(suffix) + flight::String(";\nuniform float u_fogFar") + flight::to_string(suffix) + flight::String(";\n") : flight::String("uniform float u_fogDensity") + flight::to_string(suffix) + flight::String(";\n")));
